import fs from 'node:fs';import path from 'node:path';import os from 'node:os';import assert from 'node:assert/strict';
import {setup} from './node-host.mjs';import {parseNativeJob} from '../web/job-adapter.js';import {dispatchNative} from '../web/george-entry.js';
const root=fs.mkdtempSync(path.join(os.tmpdir(),'george-integration-'));setup(root);
const f=JSON.parse(fs.readFileSync(new URL('../fixtures/fk6.json',import.meta.url)));
const rels=f.relations.map(r=>r.terms.map((t,i)=>{const c=BigInt(t.coefficient),a=c<0n?-c:c;return (c<0n?'-':i?'+':'')+(a===1n?'':a+'*')+t.word.map(k=>f.variables[k]).join('*');}).join('')).join(',');
const job={task:'gb',backend:'native',memoryMiB:128,nativeOptions:{workers:3,scratchBytes:32*1048576,spill:true},files:{'input.bg':`(ALGFORMINPUT)\nvars ${f.variables.join(',')};\n${rels};`},script:'(SETLEGACYMODE NIL)\n(NONCOMMIFY)\n(DEGLEFTLEXIFY)\n(SETMODULUS 0)\n(SETMAXDEG 4)\n(SIMPLE "input.bg" "result.gb")'};
const p=parseNativeJob(job);assert.deepEqual(p.fixture.variables,f.variables);assert.deepEqual(p.fixture.relations,f.relations);
for(const bad of ['(COMMIFY)','(SETWEIGHTS 1 2)','(EVAL FOO)'])assert.throws(()=>parseNativeJob({...job,script:job.script+'\n'+bad}));
const messages=[];const send=x=>messages.push(x);
assert.equal(await dispatchNative({id:0,command:'init',backend:'native'},send),true);
const running=dispatchNative({id:1,command:'run',job},send);
await dispatchNative({id:2,command:'run',job},send);
await running;
assert.equal(messages.find(x=>x.id===2)?.code,'BUSY');
let r=messages.find(x=>x.id===1&&x.result)?.result;assert.equal(r?.native.basisSize,265,JSON.stringify(messages));assert.equal(r.native.reduced,false);assert.ok(r.files['result.gb'].endsWith('Done\n'));
await dispatchNative({id:3,command:'run',job:{...job,script:job.script.replace('SETMAXDEG 4','SETMAXDEG 5')}},send);
r=messages.find(x=>x.id===3&&x.result)?.result;assert.equal(r?.native.completedThroughDegree,5);assert.equal(r.native.basisSize,360);
await dispatchNative({id:4,command:'run',job},send);r=messages.find(x=>x.id===4&&x.result)?.result;assert.equal(r?.native.completedThroughDegree,4);
await dispatchNative({id:5,command:'run',job:{...job,script:job.script.replace('SETMAXDEG 4','SETMAXDEG 5')}},send);
r=messages.find(x=>x.id===5&&x.result)?.result;assert.equal(r?.native.completedThroughDegree,5);
fs.writeFileSync(new URL('../results/integration-tests.json',import.meta.url),JSON.stringify({passed:true,host:'Node, actual WASM with fs storage emulation',parser:true,strictReject:true,dispatcher:true,busyProtection:true,autoResume:true,lowerTargetCheckpoint:true,browserDOMTested:false,remoteGeorgeDeploymentTested:false},null,2));
fs.rmSync(root,{recursive:true,force:true});console.log('Parser + actual WASM George worker dispatcher + resume: passed');
